### Change 1 — `src/orders.js`: add `deleteOrder(id, userId)`

Append after `createOrder`:

```js
export function deleteOrder(id, userId) {
  const index = orders.findIndex((o) => o.id === id);
  if (index === -1) return null;
  const order = orders[index];
  if (order.userId !== userId) return { forbidden: true };
  orders.splice(index, 1);
  return { deleted: true };
}
```

Return shapes: `null` → not found, `{ forbidden: true }` → wrong owner, `{ deleted: true }` → removed.

